import { expect, test, type Page } from "@playwright/test";

import { missingRoute, routes } from "./_fixtures";

// `wrangler dev` serves dist/_headers, including the policy generated by integrations/csp.ts,
// so these tests run against the same header Cloudflare sends.

async function collectViolations(page: Page) {
	await page.addInitScript(() => {
		const violations: string[] = [];
		Object.assign(window, { __cspViolations: violations });
		document.addEventListener("securitypolicyviolation", (event) => {
			violations.push(
				`${event.effectiveDirective} blocked ${event.blockedURI || "inline"} (${event.sample})`,
			);
		});
	});
}

const violations = (page: Page) =>
	page.evaluate(() => (window as unknown as { __cspViolations: string[] }).__cspViolations);

test.describe("content security policy", () => {
	test("pages send a Content-Security-Policy header", async ({ request }) => {
		const policy = (await request.get("/")).headers()["content-security-policy"];

		expect(policy).toContain("default-src 'self'");
		expect(policy).toContain("frame-ancestors 'none'");
		expect(policy).not.toMatch(/script-src[^;]*'unsafe-inline'/);
	});

	test.beforeEach(async ({ page }) => collectViolations(page));

	for (const route of [...routes, missingRoute]) {
		test(`${route} loads without violations`, async ({ page }) => {
			await page.goto(route);
			await page.waitForLoadState("networkidle");

			expect(await violations(page)).toEqual([]);
		});
	}

	test("client-side navigation runs without violations", async ({ page }) => {
		await page.goto("/");
		await page.locator('a[href="/docs/"]').first().click();
		await expect(page).toHaveURL(/\/docs\/$/);
		await page.locator("footer").getByRole("link", { name: "Privacy Policy" }).click();
		await expect(page).toHaveURL(/\/privacy-policy\/$/);

		expect(await violations(page)).toEqual([]);
	});
});
